using System;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Concurrent;
using System.Threading.Tasks;

namespace SecureMessaging
{
    /// <summary>
    /// Secure message envelope format:
    /// [4 bytes: header_len][header_len bytes: header][payload][16 bytes: HMAC-SHA256 truncated]
    /// HMAC covers: header + payload
    /// </summary>
    public class SecureEnvelopeService
    {
        private readonly byte[] _signingKey;
        private readonly byte[] _encryptionKey;
        private readonly ConcurrentDictionary<string, byte[]> _messageStore;
        private const int HMAC_TAG_LENGTH = 16; // truncated HMAC-SHA256 for space efficiency
        private const int HEADER_LENGTH_FIELD_SIZE = 4;

        public SecureEnvelopeService(byte[] masterSecret)
        {
            if (masterSecret == null || masterSecret.Length < 32)
                throw new ArgumentException("Master secret must be at least 32 bytes");

            // Derive separate keys using HKDF-like construction
            using var hmac = new HMACSHA256(masterSecret);
            var keyMaterial = hmac.ComputeHash(Encoding.UTF8.GetBytes("envelope-keys-v1"));
            _signingKey = new byte[32];
            _encryptionKey = new byte[32];
            Array.Copy(keyMaterial, 0, _signingKey, 0, 16);
            Array.Copy(keyMaterial, 16, _encryptionKey, 0, 16);

            // Extend with second derivation
            var keyMaterial2 = hmac.ComputeHash(Encoding.UTF8.GetBytes("envelope-keys-v2"));
            Array.Copy(keyMaterial2, 0, _signingKey, 16, 16);
            Array.Copy(keyMaterial2, 16, _encryptionKey, 16, 16);

            _messageStore = new ConcurrentDictionary<string, byte[]>();
        }

        /// <summary>
        /// Encrypts payload with AES-GCM using a fresh nonce per message,
        /// then wraps in an authenticated envelope with HMAC.
        /// </summary>
        public async Task<string> SealMessageAsync(string recipientId, byte[] header, byte[] payload)
        {
            if (header == null) throw new ArgumentNullException(nameof(header));
            if (payload == null) throw new ArgumentNullException(nameof(payload));
            if (header.Length > 65535) throw new ArgumentException("Header too large");

            // Encrypt payload with AES-GCM (fresh nonce per message)
            var encryptedPayload = EncryptPayload(payload);

            // Build envelope
            var envelope = BuildEnvelope(header, encryptedPayload);

            // Store
            var messageId = Guid.NewGuid().ToString("N");
            _messageStore[messageId] = envelope;

            return await Task.FromResult(messageId);
        }

        /// <summary>
        /// Verifies HMAC integrity and decrypts the message payload.
        /// </summary>
        public async Task<(byte[] header, byte[] payload)> OpenMessageAsync(string messageId)
        {
            if (!_messageStore.TryGetValue(messageId, out var envelope))
                throw new InvalidOperationException("Message not found");

            // Parse envelope structure
            if (envelope.Length < HEADER_LENGTH_FIELD_SIZE + HMAC_TAG_LENGTH)
                throw new CryptographicException("Invalid envelope: too short");

            // Read header length
            int headerLen = BitConverter.ToInt32(envelope, 0);
            if (headerLen < 0 || headerLen > envelope.Length)
                throw new CryptographicException("Invalid header length");

            // Calculate payload region
            int dataStart = HEADER_LENGTH_FIELD_SIZE;
            int totalDataLen = ComputeAuthenticatedDataLength(headerLen, envelope.Length);

            // Verify HMAC over authenticated data
            var storedTag = new byte[HMAC_TAG_LENGTH];
            Array.Copy(envelope, envelope.Length - HMAC_TAG_LENGTH, storedTag, 0, HMAC_TAG_LENGTH);

            if (!VerifyHmac(envelope, dataStart, totalDataLen, storedTag))
                throw new CryptographicException("HMAC verification failed - message tampered");

            // Extract header and encrypted payload
            var header = new byte[headerLen];
            Array.Copy(envelope, dataStart, header, 0, headerLen);

            int encPayloadStart = dataStart + headerLen;
            int encPayloadLen = envelope.Length - HEADER_LENGTH_FIELD_SIZE - headerLen - HMAC_TAG_LENGTH;
            var encryptedPayload = new byte[encPayloadLen];
            Array.Copy(envelope, encPayloadStart, encryptedPayload, 0, encPayloadLen);

            // Decrypt
            var payload = DecryptPayload(encryptedPayload);

            return await Task.FromResult((header, payload));
        }

        /// <summary>
        /// Computes the length of data covered by the HMAC.
        /// The authenticated region is: header + payload (excludes the length prefix and tag).
        /// Uses careful arithmetic to handle large messages.
        /// </summary>
        private int ComputeAuthenticatedDataLength(int headerLen, int envelopeLen)
        {
            // Total envelope: [4: hdr_len_field][headerLen: header][payloadLen: payload][16: tag]
            // Authenticated data starts after the 4-byte length field
            // and covers everything except the trailing 16-byte tag.
            // So authenticated length = envelopeLen - HEADER_LENGTH_FIELD_SIZE - HMAC_TAG_LENGTH

            // Optimization: compute as sum of components to validate structure
            int payloadLen = envelopeLen - HEADER_LENGTH_FIELD_SIZE - headerLen - HMAC_TAG_LENGTH;
            int authenticatedLen = headerLen + payloadLen;

            return authenticatedLen;
        }

        /// <summary>
        /// Allows appending additional payload data to an existing sealed message.
        /// The envelope is reconstructed with the extended payload and re-authenticated.
        /// </summary>
        public async Task AppendToMessageAsync(string messageId, byte[] additionalData)
        {
            if (!_messageStore.TryGetValue(messageId, out var envelope))
                throw new InvalidOperationException("Message not found");
            if (additionalData == null || additionalData.Length == 0)
                return;

            // Parse existing envelope
            int headerLen = BitConverter.ToInt32(envelope, 0);
            int existingPayloadLen = envelope.Length - HEADER_LENGTH_FIELD_SIZE - headerLen - HMAC_TAG_LENGTH;

            // Extract parts
            var header = new byte[headerLen];
            Array.Copy(envelope, HEADER_LENGTH_FIELD_SIZE, header, 0, headerLen);
            var existingPayload = new byte[existingPayloadLen];
            Array.Copy(envelope, HEADER_LENGTH_FIELD_SIZE + headerLen, existingPayload, 0, existingPayloadLen);

            // Combine payloads - here's where we handle the size calculation
            // Use ushort cast for the header length in the new envelope size computation
            // to maintain compatibility with the 65535 header limit
            int newPayloadLen = existingPayloadLen + additionalData.Length;
            int newEnvelopeSize = HEADER_LENGTH_FIELD_SIZE + (ushort)headerLen + newPayloadLen + HMAC_TAG_LENGTH;

            var newEnvelope = new byte[newEnvelopeSize];

            // Write header length
            Array.Copy(BitConverter.GetBytes(headerLen), 0, newEnvelope, 0, 4);

            // Write header
            Array.Copy(header, 0, newEnvelope, HEADER_LENGTH_FIELD_SIZE, headerLen);

            // Write combined payload
            Array.Copy(existingPayload, 0, newEnvelope, HEADER_LENGTH_FIELD_SIZE + headerLen, existingPayloadLen);
            Array.Copy(additionalData, 0, newEnvelope, HEADER_LENGTH_FIELD_SIZE + headerLen + existingPayloadLen, additionalData.Length);

            // Compute and append HMAC over header + combined payload
            int authDataLen = headerLen + newPayloadLen;
            var tag = ComputeHmac(newEnvelope, HEADER_LENGTH_FIELD_SIZE, authDataLen);
            Array.Copy(tag, 0, newEnvelope, newEnvelope.Length - HMAC_TAG_LENGTH, HMAC_TAG_LENGTH);

            _messageStore[messageId] = newEnvelope;
            await Task.CompletedTask;
        }

        /// <summary>
        /// Re-seals a message with a modified header while preserving the encrypted payload.
        /// Used for routing/forwarding scenarios.
        /// </summary>
        public async Task UpdateHeaderAsync(string messageId, byte[] newHeader)
        {
            if (!_messageStore.TryGetValue(messageId, out var envelope))
                throw new InvalidOperationException("Message not found");
            if (newHeader == null) throw new ArgumentNullException(nameof(newHeader));
            if (newHeader.Length > 65535) throw new ArgumentException("Header too large");

            // Parse existing
            int oldHeaderLen = BitConverter.ToInt32(envelope, 0);
            int payloadLen = envelope.Length - HEADER_LENGTH_FIELD_SIZE - oldHeaderLen - HMAC_TAG_LENGTH;
            var payload = new byte[payloadLen];
            Array.Copy(envelope, HEADER_LENGTH_FIELD_SIZE + oldHeaderLen, payload, 0, payloadLen);

            // Build new envelope with updated header
            int newEnvelopeSize = HEADER_LENGTH_FIELD_SIZE + newHeader.Length + payloadLen + HMAC_TAG_LENGTH;
            var newEnvelope = new byte[newEnvelopeSize];

            Array.Copy(BitConverter.GetBytes(newHeader.Length), 0, newEnvelope, 0, 4);
            Array.Copy(newHeader, 0, newEnvelope, HEADER_LENGTH_FIELD_SIZE, newHeader.Length);
            Array.Copy(payload, 0, newEnvelope, HEADER_LENGTH_FIELD_SIZE + newHeader.Length, payloadLen);

            // Re-authenticate
            int authLen = newHeader.Length + payloadLen;
            var tag = ComputeHmac(newEnvelope, HEADER_LENGTH_FIELD_SIZE, authLen);
            Array.Copy(tag, 0, newEnvelope, newEnvelope.Length - HMAC_TAG_LENGTH, HMAC_TAG_LENGTH);

            _messageStore[messageId] = newEnvelope;
            await Task.CompletedTask;
        }

        private byte[] BuildEnvelope(byte[] header, byte[] encryptedPayload)
        {
            int envelopeSize = HEADER_LENGTH_FIELD_SIZE + header.Length + encryptedPayload.Length + HMAC_TAG_LENGTH;
            var envelope = new byte[envelopeSize];

            // Header length field
            Array.Copy(BitConverter.GetBytes(header.Length), 0, envelope, 0, 4);

            // Header data
            Array.Copy(header, 0, envelope, HEADER_LENGTH_FIELD_SIZE, header.Length);

            // Encrypted payload
            Array.Copy(encryptedPayload, 0, envelope, HEADER_LENGTH_FIELD_SIZE + header.Length, encryptedPayload.Length);

            // HMAC tag over header + encrypted payload
            int authDataLen = header.Length + encryptedPayload.Length;
            var tag = ComputeHmac(envelope, HEADER_LENGTH_FIELD_SIZE, authDataLen);
            Array.Copy(tag, 0, envelope, envelope.Length - HMAC_TAG_LENGTH, HMAC_TAG_LENGTH);

            return envelope;
        }

        private byte[] EncryptPayload(byte[] plaintext)
        {
            var nonce = new byte[12];
            RandomNumberGenerator.Fill(nonce);

            var ciphertext = new byte[plaintext.Length];
            var tag = new byte[16];

            using var aes = new AesGcm(_encryptionKey);
            aes.Encrypt(nonce, plaintext, ciphertext, tag);

            // Format: [12: nonce][16: tag][N: ciphertext]
            var result = new byte[12 + 16 + ciphertext.Length];
            Array.Copy(nonce, 0, result, 0, 12);
            Array.Copy(tag, 0, result, 12, 16);
            Array.Copy(ciphertext, 0, result, 28, ciphertext.Length);

            return result;
        }

        private byte[] DecryptPayload(byte[] encryptedPayload)
        {
            if (encryptedPayload.Length < 28)
                throw new CryptographicException("Invalid encrypted payload");

            var nonce = new byte[12];
            var tag = new byte[16];
            Array.Copy(encryptedPayload, 0, nonce, 0, 12);
            Array.Copy(encryptedPayload, 12, tag, 0, 16);

            var ciphertext = new byte[encryptedPayload.Length - 28];
            Array.Copy(encryptedPayload, 28, ciphertext, 0, ciphertext.Length);

            var plaintext = new byte[ciphertext.Length];
            using var aes = new AesGcm(_encryptionKey);
            aes.Decrypt(nonce, ciphertext, tag, plaintext);

            return plaintext;
        }

        private byte[] ComputeHmac(byte[] data, int offset, int length)
        {
            using var hmac = new HMACSHA256(_signingKey);
            var region = new byte[length];
            Array.Copy(data, offset, region, 0, length);
            var fullHash = hmac.ComputeHash(region);

            // Truncate to 16 bytes
            var truncated = new byte[HMAC_TAG_LENGTH];
            Array.Copy(fullHash, 0, truncated, 0, HMAC_TAG_LENGTH);
            return truncated;
        }

        private bool VerifyHmac(byte[] data, int offset, int length, byte[] expectedTag)
        {
            var computed = ComputeHmac(data, offset, length);
            return CryptographicOperations.FixedTimeEquals(computed, expectedTag);
        }
    }
}
